using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "recent advances in quantum computing 2026";

Console.WriteLine($"🔍 Research Agent — topic: \"{topic}\"\n");

// --- Tools -----------------------------------------------------------

var notes = new List<string>();

var searchTool = AIFunctionFactory.Create(SearchWebAsync, new AIFunctionFactoryOptions
{
    Name = "search_web",
    Description = "Search the web for information on a query. Returns a list of result snippets.",
});

var noteTools = AIFunctionFactory.Create(SaveNote, new AIFunctionFactoryOptions
{
    Name = "save_note",
    Description = "Save an important finding or fact as a research note for later summarization.",
});

var getNotesTool = AIFunctionFactory.Create(GetNotes, new AIFunctionFactoryOptions
{
    Name = "get_notes",
    Description = "Retrieve all saved research notes collected so far.",
});

// --- Agent setup -----------------------------------------------------

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient("gpt-4o-mini-2024-07-18")
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient: chatClient,
    instructions: """
        You are a research assistant. Given a topic, you must:
        1. Search the web multiple times with varied queries to gather diverse information.
        2. Save each key finding as a note using the save_note tool.
        3. After gathering enough information (at least 3-5 searches), retrieve your notes
           and produce a comprehensive summary with sections and bullet points.
        Always end with a final summary of your findings.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: [searchTool, noteTools, getNotesTool]);

var session = await agent.CreateSessionAsync("research-session");

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

// --- Run the agent ---------------------------------------------------

var result = await agent.RunAsync(
    $"Research the following topic thoroughly and provide a summary: {topic}",
    session,
    runOptions);

Console.WriteLine("\n📋 Agent Response:\n");
Console.WriteLine(result.Text);
Console.WriteLine($"\n✅ Done — {notes.Count} note(s) saved during research.");

// --- Tool implementations --------------------------------------------

[Description("Search the web for information on a query. Returns a list of result snippets.")]
static async Task<string> SearchWebAsync(
    [Description("The search query")] string query)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

    // Use DuckDuckGo Instant Answer API (no key required)
    var encoded = Uri.EscapeDataString(query);
    var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

    try
    {
        var response = await http.GetFromJsonAsync<JsonElement>(url);
        var results = new List<string>();

        // Abstract text
        if (response.TryGetProperty("AbstractText", out var abs) &&
            abs.GetString() is { Length: > 0 } abstractText)
        {
            results.Add($"[Abstract] {abstractText}");
        }

        // Related topics
        if (response.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var item in topics.EnumerateArray().Take(5))
            {
                if (item.TryGetProperty("Text", out var text) &&
                    text.GetString() is { Length: > 0 } snippet)
                {
                    results.Add(snippet);
                }
            }
        }

        if (results.Count == 0)
            results.Add($"No detailed results found for '{query}'. Try a different search query.");

        return string.Join("\n\n", results);
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}. Try a different query.";
    }
}

[Description("Save an important finding or fact as a research note.")]
string SaveNote([Description("The note content to save")] string note)
{
    notes.Add(note);
    return $"Note #{notes.Count} saved successfully.";
}

[Description("Retrieve all saved research notes collected so far.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n", notes.Select((n, i) => $"[{i + 1}] {n}"));
}

using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var topic = args.Length > 0
